// Anchoring a floating panel.
//
// IT LIVES HERE, NOT IN THE DOCUMENTATION SITE, because `ColorPicker` ships its
// behaviour and a shipped panel cannot import from `docs-site/`. It was
// `shell.js:483-586` and it moved unchanged; `shell.js` imports it back, the
// way it already imports `./lineage.js`. Its three call sites there — the
// frame's theme menu, `Select`, and `TagPicker`/`DateInput` — did not move and
// did not change. This deletes a copy rather than making one.
//
// A PANEL ITS OWN ANCESTOR CANNOT CLIP, WHICH MEANS IT CANNOT BE POSITIONED IN
// CSS.
//
// The frame's theme menu used to be a band inside the frame, and a frame is not
// tall enough to hold it: 457px of panel in a 172px frame, under
// `overflow: clip`, is a menu that opens into nothing. It floats, which takes
// `position: fixed` — the one kind of descendant an ancestor's `overflow` does
// not clip. The cost of `fixed` is that CSS has nothing to hang it from: the
// bar it belongs to is `sticky`, so where the control IS depends on the scroll.
// Two custom properties carry that, written here and read by the stylesheet.
//
// ONE FUNCTION, THREE PANELS, ONE LISTENER. This was two near-identical copies
// — one for the frame's menu and one for the Select's — each followed by its
// own scroll listener repeating the same off-screen test in its own words. The
// second said so in a comment: "the frame's menu closes for the same reason and
// this borrows its rule". A third floating surface would have made three, so
// the extraction takes the listeners with it.

/** The least window a floating panel leaves beside itself. */
const GLASS_PANEL_GUTTER = 16;

/** Below this much room under a control, a panel opens above it instead. */
const GLASS_PANEL_ROOM = 240;

/**
 * Puts a fixed panel under — or over — the control it belongs to.
 *
 * `width`, when given, is a custom property set to the control's own width,
 * which is what makes a panel read as the control opening rather than as a menu
 * appearing beside one.
 *
 * `offScreen` comes back rather than being re-derived by each caller, because
 * it already had been, twice: a panel whose control has scrolled away is a
 * panel pointing at something the reader can no longer see, and closing is the
 * only honest answer.
 */
function anchorPanel(control, panel, { room = GLASS_PANEL_ROOM, width = null } = {}) {
  const box = control.getBoundingClientRect();
  if (box.bottom < 0 || box.top > innerHeight) {
    return { flipped: panel.hasAttribute("data-nd-above"), offScreen: true };
  }
  // IT OPENS UPWARDS WHEN THERE IS NO ROOM DOWNWARDS.
  //
  // A control low on the page has almost nothing under it, and
  // `max-block-size: 100vh - anchor` then resolves to a sliver: the menu opened
  // as a band at the bottom edge with its rows below the fold. Measured on the
  // nested frame at 768px — every row of six at y=725 in an 800px window, and
  // `elementFromPoint` returning null for all of them. The flip is the ordinary
  // popover answer and the condition is the ordinary one: go up only when there
  // is genuinely more room up there.
  const below = innerHeight - box.bottom;
  const flipped = below < room && box.top > below;
  panel.toggleAttribute("data-nd-above", flipped);
  panel.style.setProperty(
    "--nd-anchor-block",
    `${Math.round(flipped ? innerHeight - box.top : box.bottom)}px`,
  );
  // AND IT STAYS INSIDE THE WINDOW. The panel hangs from its control's trailing
  // edge, and a control in a narrow frame's toolbar has less room beside it
  // than the panel is wide: at 768px the nested frame's menu started at x = -86
  // and every row of it was outside the window. Anchoring is a preference;
  // being on screen is not.
  const free = innerWidth - panel.offsetWidth - GLASS_PANEL_GUTTER;
  const inline = Math.min(Math.max(0, innerWidth - box.right), Math.max(0, free));
  panel.style.setProperty("--nd-anchor-inline", `${Math.round(inline)}px`);
  // AND THE OTHER EDGE, for a panel that reads better hanging the other way.
  //
  // Five callers hang a panel's TRAILING edge off a control's, which is right
  // for a menu at the end of a toolbar. A note beside a word in running text is
  // the opposite case: aligned that way it reaches back across the sentence it
  // is about. Both distances are written and the stylesheet picks, so no
  // caller had to change and none of them can disagree about the measurement.
  const start = Math.min(Math.max(0, box.left), Math.max(0, free));
  panel.style.setProperty("--nd-anchor-start", `${Math.round(start)}px`);
  if (width) panel.style.setProperty(width, `${Math.round(box.width)}px`);
  return { flipped, offScreen: false };
}

/** Every open floating panel, and what to do when its control leaves. */
const anchored = new Map();

export function keepAnchored(panel, control, options, close) {
  // THE CONTROL CAN CHANGE SHAPE WHILE THE PANEL IS OPEN, and scroll and resize
  // do not see that. A `TagPicker` grows a row every time a tag is committed
  // with the list still open; the panel would stay where it was measured and
  // float over the field it belongs to. One observer per panel, released with
  // it, and it benefits the two call sites that came first as well.
  const watch = new ResizeObserver(() => {
    const entry = anchored.get(panel);
    if (entry) anchorPanel(entry.control, panel, entry.options);
  });
  watch.observe(control);
  anchored.set(panel, { control, options, close, watch });
  anchorPanel(control, panel, options);
}

export function releaseAnchor(panel) {
  anchored.get(panel)?.watch?.disconnect();
  anchored.delete(panel);
}

// One pass, one listener, however many kinds of panel this file grows.
// Passive: it only reads geometry and writes custom properties, so it must
// never be a reason a scroll janks.
function reanchor() {
  for (const [panel, entry] of anchored) {
    if (anchorPanel(entry.control, panel, entry.options).offScreen) entry.close();
  }
}
addEventListener("scroll", reanchor, { passive: true });
addEventListener("resize", reanchor, { passive: true });
